#include <iostream>
#include <vector>

// Function to check if a number is prime
bool isPrime(int num) {
    if (num <= 1) return false;
    for (int i = 2; i * i <= num; ++i) {
        if (num % i == 0) return false;
    }
    return true;
}

// Function to print all prime numbers up to a given limit
void printPrimes(int limit) {
    for (int i = 2; i <= limit; ++i) {
        if (isPrime(i)) {
            std::cout << i << " ";
        }
    }
    std::cout << std::endl;
}

// Main function
int main() {
    int limit;
    std::cout << "Enter the limit for prime numbers: ";
    std::cin >> limit;
    printPrimes(limit);
    return 0;
}
```

数组旋转打印思路：
1. 确定旋转的步数 `k`，可以通过取模操作 `k = k % n` 来处理 `k` 大于数组长度的情况。
2. 将数组分为两部分：前 `n-k` 个元素和后 `k` 个元素。
3. 反转前 `n-k` 个元素，反转后 `k` 个元素，然后反转整个数组。
4. 输出旋转后的数组。

具体步骤：
- 反转数组的前 `n-k` 个元素。
- 反转数组的后 `k` 个元素。
- 反转整个数组。

示例代码：
```cpp
#include <iostream>
#include <vector>
#include <algorithm>

// Function to rotate the array
void rotateArray(std::vector<int>& arr, int k) {
    int n = arr.size();
    k = k % n; // Handle cases where k > n
    std::reverse(arr.begin(), arr.begin() + n - k);
    std::reverse(arr.begin() + n - k, arr.end());
    std::reverse(arr.begin(), arr.end());
}

// Main function
int main() {
    std::vector<int> arr = {1, 2, 3, 4, 5, 6, 7};
    int k = 3; // Number of rotations
    rotateArray(arr, k);

    for (int num : arr) {
        std::cout << num << " ";
    }
    std::cout << std::endl;
    return 0;
}
```

Java 的线程是 Java 中实现并发编程的基本单位。线程是进程中的一个执行路径，一个进程可以包含多个线程。Java 提供了多种方式来创建和管理线程，主要有以下两种：

1. **继承 `Thread` 类**：通过创建一个继承自 `Thread` 的子类，重写 `run()` 方法，然后创建该子类的实例并调用 `start()` 方法来启动线程。

   ```java
   class MyThread extends Thread {
       public void run() {
           // 线程执行的代码
       }
   }

   MyThread thread = new MyThread();
   thread.start();
   ```

2. **实现 `Runnable` 接口**：通过实现 `Runnable` 接口并重写 `run()` 方法，然后将该实现传递给 `Thread` 类的构造函数，最后调用 `start()` 方法启动线程。

   ```java
   class MyRunnable implements Runnable {
       public void run() {
           // 线程执行的代码
       }
   }

   Thread thread = new Thread(new MyRunnable());
   thread.start();
   ```

Java 线程的主要特性包括：

- **线程状态**：线程可以处于新建、就绪、运行、阻塞和死亡等状态。
- **线程同步**：为了避免多个线程同时访问共享资源导致的数据不一致，Java 提供了 `synchronized` 关键字和其他同步机制（如 `Lock` 接口）。
- **线程间通信**：可以使用 `wait()`、`notify()` 和 `notifyAll()` 方法进行线程间的通信。
- **线程池**：Java 提供了 `Executor` 框架，可以通过线程池来管理线程的创建和生命周期，提高性能和资源利用率。

Java 线程的使用可以提高程序的效率，特别是在处理 I/O 密集型或 CPU 密集型任务时。

LRU（Least Recently Used）算法是一种常用的缓存淘汰策略，主要用于管理缓存中的数据。下面是一个使用 Python 实现 LRU 缓存的示例，使用 `OrderedDict` 来保持元素的顺序：

```python
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        self.cache = OrderedDict()
        self.capacity = capacity

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        else:
            # Move the accessed item to the end (most recently used)
            self.cache.move_to_end(key)
            return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            # Update the value and move to end
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            # Remove the first item (least recently used)
            self.cache.popitem(last=False)

# 示例用法
lru_cache = LRUCache(2)
lru_cache.put(1, 1)  # 缓存是 {1=1}
lru_cache.put(2, 2)  # 缓存是 {1=1, 2=2}
print(lru_cache.get(1))  # 返回 1
lru_cache.put(3, 3)      # 淘汰 key 2，缓存是 {1=1, 3=3}
print(lru_cache.get(2))  # 返回 -1 (未找到)
lru_cache.put(4, 4)      # 淘汰 key 1，缓存是 {3=3, 4=4}
print(lru_cache.get(1))  # 返回 -1 (未找到)
print(lru_cache.get(3))  # 返回 3
print(lru_cache.get(4))  # 返回 4
```

这个实现使用了 `OrderedDict` 来保持插入顺序，`get` 方法用于获取缓存中的值并更新其使用顺序，`put` 方法用于添加或更新缓存中的值，并在超出容量时淘汰最久未使用的项。

可以使用 `volatile` 关键字来确保线程之间的可见性，从而实现线程交替打印 ABC 的功能。以下是一个简单的 Java 示例代码：

```java
public class PrintABC {
    private static volatile int flag = 0; // 0: A, 1: B, 2: C

    public static void main(String[] args) {
        Thread threadA = new Thread(() -> {
            for (int i = 0; i < 5; i++) {
                while (flag != 0) {
                    // 等待
                }
                System.out.print("A");
                flag = 1; // 设置为 B
            }
        });

        Thread threadB = new Thread(() -> {
            for (int i = 0; i < 5; i++) {
                while (flag != 1) {
                    // 等待
                }
                System.out.print("B");
                flag = 2; // 设置为 C
            }
        });

        Thread threadC = new Thread(() -> {
            for (int i = 0; i < 5; i++) {
                while (flag != 2) {
                    // 等待
                }
                System.out.print("C");
                flag = 0; // 设置为 A
            }
        });

        threadA.start();
        threadB.start();
        threadC.start();
    }
}
```

在这个例子中，三个线程分别打印 A、B 和 C。`volatile` 关键字确保了 `flag` 的值在不同线程之间的可见性，从而实现了线程的交替执行。每个线程在打印自己的字符之前，都会检查 `flag` 的值，确保按照顺序执行。

头插和尾插是链表操作中的两种基本插入方式。以下是它们的具体实现细节：

1. **头插法**：
   - 创建一个新节点，将其数据域赋值为要插入的值。
   - 将新节点的指针指向当前链表的头节点。
   - 更新链表的头指针，使其指向新节点。

   示例代码（假设链表节点结构为`Node`）：
   ```cpp
   struct Node {
       int data;
       Node* next;
   };

   void insertAtHead(Node*& head, int value) {
       Node* newNode = new Node();
       newNode->data = value;
       newNode->next = head;
       head = newNode;
   }
   ```

2. **尾插法**：
   - 创建一个新节点，将其数据域赋值为要插入的值。
   - 如果链表为空，将头指针指向新节点。
   - 如果链表不为空，遍历链表找到最后一个节点，将其指针指向新节点。

   示例代码：
   ```cpp
   void insertAtTail(Node*& head, int value) {
       Node* newNode = new Node();
       newNode->data = value;
       newNode->next = nullptr;

       if (head == nullptr) {
           head = newNode;
       } else {
           Node* temp = head;
           while (temp->next != nullptr) {
               temp = temp->next;
           }
           temp->next = newNode;
       }
   }
   ```

这两种方法的时间复杂度分别为 O(1)（头插）和 O(n)（尾插，最坏情况下需要遍历整个链表）。

