        # 发送数据包的逻辑
        print(f"Sending packet: {packet}")

    def receive_ack(self, ack):
        if ack in self.sent_packets:
            self.acknowledged_packets.add(ack)
            self.sent_packets.remove(ack)
            self.slide_window()

    def slide_window(self):
        # 滑动窗口逻辑
        print(f"Sliding window. Acknowledged packets: {self.acknowledged_packets}")
```

