def flatten_array(arr):
    flat_list = []
    for item in arr:
        if isinstance(item, list):
            flat_list.extend(flatten_array(item))
        else:
            flat_list.append(item)
    return flat_list

def most_frequent_letter_sum(arr):
    flat_list = flatten_array(arr)
    letter_count = {}
    letter_sum = {}

    for i in range(len(flat_list) - 1):
        if isinstance(flat_list[i], int) and isinstance(flat_list[i + 1], str):
            letter = flat_list[i + 1]
            number = flat_list[i]

            # 更新字母出现次数
            if letter in letter_count:
                letter_count[letter] += 1
                letter_sum[letter] += number
            else:
                letter_count[letter] = 1
                letter_sum[letter] = number

    # 找到出现次数最多的字母
    max_count = 0
    result_letter = None
    for letter, count in letter_count.items():
        if count > max_count:
            max_count = count
            result_letter = letter

    return result_letter, letter_sum[result_letter] if result_letter else None

