`addEventListener` 是一个用于在 DOM 元素上注册事件处理程序的方法。其基本实现可以通过以下步骤来模拟：

```javascript
// 创建一个简单的事件管理器
function EventTarget() {
    this.listeners = {};
}

// 添加事件监听器
EventTarget.prototype.addEventListener = function(type, listener) {
    if (!this.listeners[type]) {
        this.listeners[type] = [];
    }
    this.listeners[type].push(listener);
};

// 移除事件监听器
EventTarget.prototype.removeEventListener = function(type, listener) {
    if (!this.listeners[type]) return;

    this.listeners[type] = this.listeners[type].filter(function(l) {
        return l !== listener;
    });
};

// 触发事件
EventTarget.prototype.dispatchEvent = function(type, event) {
    if (!this.listeners[type]) return;

    this.listeners[type].forEach(function(listener) {
        listener(event);
    });
};

// 使用示例
const target = new EventTarget();

function onClick(event) {
    console.log('Element clicked!', event);
}

target.addEventListener('click', onClick);
target.dispatchEvent('click', { detail: 'Some event data' }); // 触发事件
target.removeEventListener('click', onClick);
```

在这个实现中，我们创建了一个 `EventTarget` 类，它可以添加、移除和触发事件监听器。通过 `addEventListener` 方法，我们可以将监听器添加到特定类型的事件中。

