# LeetCode 300: Longest Increasing Subsequence

def lengthOfLIS(nums):
    if not nums:
        return 0

    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

# 打印最长递增子序列
def printLIS(nums):
    if not nums:
        return []

    dp = [1] * len(nums)
    prev = [-1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1
                prev[i] = j

    max_length = max(dp)
    index = dp.index(max_length)

    lis = []
    while index != -1:
        lis.append(nums[index])
        index = prev[index]

    return lis[::-1]  # Reverse the list to get the correct order

