```cpp
template <typename T>
class auto_ptr {
private:
    T* ptr;

public:
    explicit auto_ptr(T* p = nullptr) : ptr(p) {}

    // 禁用拷贝构造，防止多个auto_ptr管理同一资源
    auto_ptr(const auto_ptr& other) = delete;

    // 转移所有权的构造函数
    auto_ptr(auto_ptr&& other) noexcept : ptr(other.ptr) {
        other.ptr = nullptr;
    }

    // 转移所有权的赋值操作符
    auto_ptr& operator=(auto_ptr&& other) noexcept {
        if (this != &other) {
            delete ptr;
            ptr = other.ptr;
            other.ptr = nullptr;
        }
        return *this;
    }

    // 禁用拷贝赋值
    auto_ptr& operator=(const auto_ptr& other) = delete;

    ~auto_ptr() {
        delete ptr;
    }

    T& operator*() const {
        return *ptr;
    }

    T* operator->() const {
        return ptr;
    }

    T* get() const {
        return ptr;
    }

    T* release() {
        T* temp = ptr;
        ptr = nullptr;
        return temp;
    }

    void reset(T* p = nullptr) {
        if (ptr != p) {
            delete ptr;
            ptr = p;
        }
    }
};
