```python
def count_occurrences(nums, target):
    def find_left_boundary():
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def find_right_boundary():
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] <= target:
                left = mid + 1
            else:
                right = mid - 1
        return right

    left_idx = find_left_boundary()
    right_idx = find_right_boundary()

    if left_idx <= right_idx and 0 <= left_idx < len(nums) and nums[left_idx] == target:
        return right_idx - left_idx + 1
    return 0
```

