```java
// Definition for singly-linked list with a random pointer.
class Node {
    int val;
    Node next;
    Node random;

    public Node(int val) {
        this.val = val;
        this.next = null;
        this.random = null;
    }
}

public class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) return null;

        // 1.复制每个节点，插入到原节点后面
        Node curr = head;
        while (curr != null) {
            Node copy = new Node(curr.val);
            copy.next = curr.next;
            curr.next = copy;
            curr = copy.next;
        }

        // 2.设置复制节点的random指针
        curr = head;
        while (curr != null) {
            if (curr.random != null) {
                curr.next.random = curr.random.next;
            }
            curr = curr.next.next;
        }

        // 3.拆分链表，恢复原链表，返回复制链表
        Node pseudoHead = new Node(0);
        Node copyCurr = pseudoHead;
        curr = head;
        while (curr != null) {
            Node copy = curr.next;
            copyCurr.next = copy;
            copyCurr = copy;

            // 恢复原链表
            curr.next = copy.next;
            curr = curr.next;
        }

        return pseudoHead.next;
    }
}
