        size_t len = std::strlen(str);
        if (size + len >= capacity) {
            resize((size + len) * 2);
        }
        std::memcpy(data + size, str, len);
        size += len;
        data[size] = '\0';
    }

    const char* c_str() const {
        return data;
    }
};

