Array.prototype.flat = function(depth = 1) {
  const result = [];
  const flatten = (arr, currentDepth) => {
    for (let item of arr) {
      if (Array.isArray(item) && currentDepth < depth) {
        flatten(item, currentDepth + 1);
      } else {
        result.push(item);
      }
    }
  };
  flatten(this, 0);
  return result;
};
